//! Measure what the README reports, and write it there.
//!
//! The README's measured tables, and the instruction-count table in
//! `docs/testing.md`, are generated: copying numbers out of harness logs by hand
//! is how they went stale. This task takes the measurements and rewrites each
//! table between its markers,
//!
//! ```text
//! <!-- generated by `cargo xtask measure`: NAME -->
//! ...
//! <!-- end of generated: NAME -->
//! ```
//!
//! from three sources:
//!
//! - **The bare-metal harness**, under `qemu-system-arm -icount shift=0`, in all
//!   four filter configurations on the Cortex-M4 (`f64` in software), the
//!   Cortex-M7 (`f64` in hardware), and the Cortex-M7 at `opt-level = 3`:
//!   instructions per `add_imu` and the peak stack. Under `-icount` the counts
//!   are exact and do not depend on the host. Each run's log is kept in
//!   `cortex-m-harness/target/measure/`.
//! - **The KF-GINS regression test**, whose `MEASURED` line gives the accuracy,
//!   the dataset's size, and how long the replay took. It needs the dataset
//!   (`scripts/fetch-kf-gins.sh`).
//! - **The test count**, from `cargo test -- --list` over the workspace with
//!   every feature on, leaving out `drifters-interop` as CI does.
//!
//! `--check` measures and compares without writing, and fails if a table would
//! change. `--reuse-logs` skips a harness run whose log is already there.
//! `--machine "..."` names the computer the replay was timed on; without it the
//! README's existing description is kept, so pass it when measuring elsewhere.

use std::collections::BTreeMap;
use std::error::Error;
use std::fs::{self, File};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use crate::repo_root;

type Result<T> = std::result::Result<T, Box<dyn Error>>;

/// One way of building the harness.
struct Build {
    name: &'static str,
    machine: &'static str,
    cpu: &'static str,
    /// Relative to `cortex-m-harness`, and shared with `check-core.sh`.
    target_dir: &'static str,
    /// What puts `f64` on the Cortex-M7's double-precision FPU.
    double_precision_fpu: bool,
    opt_level_3: bool,
}

const BUILDS: [Build; 3] = [
    Build {
        name: "m4",
        machine: "mps2-an386",
        cpu: "cortex-m4",
        target_dir: "target",
        double_precision_fpu: false,
        opt_level_3: false,
    },
    Build {
        name: "m7",
        machine: "mps2-an500",
        cpu: "cortex-m7",
        target_dir: "target-m7",
        double_precision_fpu: true,
        opt_level_3: false,
    },
    Build {
        name: "m7-o3",
        machine: "mps2-an500",
        cpu: "cortex-m7",
        target_dir: "target-m7-o3",
        double_precision_fpu: true,
        opt_level_3: true,
    },
];

/// The four filter configurations, as `check-core.sh` names them.
const CONFIGURATIONS: [(&str, Option<&str>); 4] = [
    ("default", None),
    ("f32", Some("f32-covariance")),
    ("reduced", Some("reduced-state")),
    ("reduced-f32", Some("reduced-state,f32-covariance")),
];

/// A QEMU run that takes longer than this has hung.
const RUN_TIMEOUT: Duration = Duration::from_secs(900);

pub fn run(flags: &[String]) -> Result<()> {
    let check = flags.iter().any(|f| f == "--check");
    let reuse = flags.iter().any(|f| f == "--reuse-logs");
    let machine = flag_value(flags, "--machine")?;

    let root = repo_root();
    let readme_path = root.join("README.md");
    let testing_path = root.join("docs/testing.md");
    let readme = fs::read_to_string(&readme_path)?;
    let testing = fs::read_to_string(&testing_path)?;

    let harness = measure_harness(&root, reuse)?;
    let mut replay = measure_replay(&root)?;
    if check {
        // The replay time is the one figure that moves from run to run, so a
        // check compares everything else and keeps the time the README has.
        replay.replay_s = existing_replay_time(&readme)?;
    }
    let tests = count_tests(&root)?;
    let rust = rust_version()?;
    let machine = match machine {
        Some(m) => m,
        None => existing_machine(&readme)?,
    };
    let eqf_ceiling = eqf_ceiling(&root)?;

    let blocks = [
        (
            "readme-performance",
            render_performance(&harness, &replay, tests, eqf_ceiling, &machine, &rust)?,
        ),
        ("readme-instructions", render_instructions(&harness)?),
    ];
    let new_readme = replace_blocks(&readme, &blocks)?;
    let new_testing = replace_blocks(
        &testing,
        &[("testing-instructions", render_testing(&harness, &rust)?)],
    )?;

    let mut stale = Vec::new();
    let mut wrote = false;
    for (path, old, new) in [
        (&readme_path, &readme, &new_readme),
        (&testing_path, &testing, &new_testing),
    ] {
        if old == new {
            continue;
        }
        let shown = path
            .strip_prefix(&root)
            .unwrap_or(path)
            .display()
            .to_string();
        if check {
            stale.push(shown);
        } else {
            fs::write(path, new)?;
            println!("wrote {shown}");
            wrote = true;
        }
    }
    if check {
        if !stale.is_empty() {
            return Err(format!(
                "measured tables are out of date in {} — run `cargo xtask measure`",
                stale.join(", ")
            )
            .into());
        }
        println!("measured tables are up to date");
    } else if !wrote {
        println!("measured tables were already up to date");
    }
    Ok(())
}

fn flag_value(flags: &[String], name: &str) -> Result<Option<String>> {
    match flags.iter().position(|f| f == name) {
        None => Ok(None),
        Some(i) => flags
            .get(i + 1)
            .cloned()
            .map(Some)
            .ok_or_else(|| format!("{name} needs a value").into()),
    }
}

// --- the harness ---------------------------------------------------------

/// Instruction counts and stack peaks from one harness run.
#[derive(Default)]
struct HarnessRun {
    /// `INSTRUCTIONS_EQF add_imu = N (T ticks; ...)` as `"INSTRUCTIONS_EQF"` to
    /// `(N, T)`. Only the `add_imu` lines.
    instructions: BTreeMap<String, (u64, u64)>,
    /// `PEAK_EQF  N` as `"PEAK_EQF"` to `N`.
    peaks: BTreeMap<String, u64>,
}

impl HarnessRun {
    fn parse(log: &str) -> Result<Self> {
        let mut run = Self::default();
        for line in log.lines() {
            let tokens: Vec<&str> = line.split_whitespace().collect();
            match tokens.as_slice() {
                [label, "add_imu", "=", rest @ ..] if label.starts_with("INSTRUCTIONS") => {
                    let count = rest
                        .first()
                        .and_then(|n| n.parse().ok())
                        .ok_or_else(|| format!("unmeasured: {line}"))?;
                    let ticks = rest
                        .get(1)
                        .and_then(|t| t.trim_start_matches('(').parse().ok())
                        .ok_or_else(|| format!("no tick count: {line}"))?;
                    run.instructions
                        .insert((*label).to_string(), (count, ticks));
                }
                [label, value] if label.starts_with("PEAK") => {
                    if let Ok(bytes) = value.parse() {
                        run.peaks.insert((*label).to_string(), bytes);
                    }
                }
                _ => {}
            }
        }
        if !run.instructions.contains_key("INSTRUCTIONS") || !run.peaks.contains_key("PEAK") {
            return Err(
                "the log has no instruction count or peak: did QEMU run with \
                        `-icount shift=0`?"
                    .into(),
            );
        }
        Ok(run)
    }

    fn instructions(&self, label: &str) -> Result<u64> {
        self.count_and_ticks(label).map(|(n, _)| n)
    }

    fn count_and_ticks(&self, label: &str) -> Result<(u64, u64)> {
        self.instructions
            .get(label)
            .copied()
            .ok_or_else(|| format!("the harness reported no {label}").into())
    }

    fn peak(&self, label: &str) -> Result<u64> {
        self.peaks
            .get(label)
            .copied()
            .ok_or_else(|| format!("the harness reported no {label}").into())
    }
}

/// Every run, keyed by `(build, configuration)`.
type Harness = BTreeMap<(&'static str, &'static str), HarnessRun>;

fn measure_harness(root: &Path, reuse: bool) -> Result<Harness> {
    let dir = root.join("cortex-m-harness");
    let logs = dir.join("target/measure");
    fs::create_dir_all(&logs)?;
    let mut harness = Harness::new();
    for build in &BUILDS {
        for (configuration, features) in CONFIGURATIONS {
            let log = logs.join(format!("{}-{configuration}.log", build.name));
            let reusable = reuse
                && fs::read_to_string(&log)
                    .ok()
                    .and_then(|text| HarnessRun::parse(&text).ok())
                    .is_some();
            if !reusable {
                println!("=== harness: {}, {configuration}", build.name);
                let elf = build_harness(&dir, build, features)?;
                // The next configuration's build overwrites the binary, so each
                // run starts from a copy of its own.
                let copy = logs.join(format!("{}-{configuration}.elf", build.name));
                fs::copy(&elf, &copy)?;
                run_qemu(build, &copy, &log)?;
            }
            let text = fs::read_to_string(&log)?;
            let run = HarnessRun::parse(&text).map_err(|e| format!("{}: {e}", log.display()))?;
            harness.insert((build.name, configuration), run);
        }
    }
    Ok(harness)
}

fn build_harness(dir: &Path, build: &Build, features: Option<&str>) -> Result<PathBuf> {
    let mut cargo = Command::new("cargo");
    cargo
        .current_dir(dir)
        .args(["build", "--release", "--bin", "cortex-m-harness"])
        .env("CARGO_TARGET_DIR", build.target_dir);
    if let Some(features) = features {
        cargo.args(["--features", features]);
    }
    if build.double_precision_fpu {
        let existing = std::env::var("RUSTFLAGS").unwrap_or_default();
        cargo.env("RUSTFLAGS", format!("{existing} -C target-cpu=cortex-m7"));
    }
    if build.opt_level_3 {
        cargo.env("CARGO_PROFILE_RELEASE_OPT_LEVEL", "3");
    }
    let status = cargo.status()?;
    if !status.success() {
        return Err(format!("building the harness for {} failed", build.name).into());
    }
    Ok(dir
        .join(build.target_dir)
        .join("thumbv7em-none-eabihf/release/cortex-m-harness"))
}

fn run_qemu(build: &Build, elf: &Path, log: &Path) -> Result<()> {
    // Output goes straight to the log, so a full pipe cannot stall the run.
    let mut child = Command::new("qemu-system-arm")
        .args(["-machine", build.machine, "-cpu", build.cpu, "-nographic"])
        .args(["-semihosting-config", "enable=on,target=native"])
        .args(["-icount", "shift=0", "-kernel"])
        .arg(elf)
        .stdin(Stdio::null())
        .stdout(File::create(log)?)
        .stderr(Stdio::inherit())
        .spawn()
        .map_err(|e| {
            format!("starting qemu-system-arm: {e} (scripts/install-qemu.sh puts one on PATH)")
        })?;
    let deadline = Instant::now() + RUN_TIMEOUT;
    loop {
        if let Some(status) = child.try_wait()? {
            if !status.success() {
                return Err(format!(
                    "the harness failed on {}: see {}",
                    build.name,
                    log.display()
                )
                .into());
            }
            return Ok(());
        }
        if Instant::now() > deadline {
            child.kill()?;
            return Err(format!("QEMU timed out on {}", build.name).into());
        }
        std::thread::sleep(Duration::from_millis(100));
    }
}

/// The equivariant filter's stack ceiling, from the script CI enforces it in.
fn eqf_ceiling(root: &Path) -> Result<u64> {
    let script = fs::read_to_string(root.join("cortex-m-harness/check-core.sh"))?;
    script
        .lines()
        .find_map(|line| line.strip_prefix("eqf_ceiling="))
        .and_then(|value| value.trim().parse().ok())
        .ok_or_else(|| "check-core.sh sets no eqf_ceiling".into())
}

// --- the host -------------------------------------------------------------

/// The `MEASURED kf_gins` line from the regression test.
struct Replay {
    imu_samples: u64,
    gnss_fixes: u64,
    duration_s: f64,
    horizontal_rms_m: f64,
    vertical_rms_m: f64,
    max_axis_bias_m: f64,
    replay_s: f64,
}

fn measure_replay(root: &Path) -> Result<Replay> {
    println!("=== the KF-GINS regression test");
    let output = Command::new("cargo")
        .current_dir(root)
        .args(["test", "--release", "-p", "drifters-cli"])
        .args(["--test", "kf_gins_regression", "--", "--nocapture"])
        // Absent data must fail here, not skip and report nothing.
        .env("DRIFTERS_DATASET_REQUIRED", "1")
        .stderr(Stdio::inherit())
        .output()?;
    if !output.status.success() {
        return Err("the KF-GINS regression test failed or has no dataset; \
                    `scripts/fetch-kf-gins.sh` fetches it"
            .into());
    }
    let stdout = String::from_utf8(output.stdout)?;
    let line = stdout
        .lines()
        .find(|l| l.starts_with("MEASURED kf_gins "))
        .ok_or("the regression test printed no MEASURED line")?;
    let fields: BTreeMap<&str, &str> = line
        .split_whitespace()
        .filter_map(|field| field.split_once('='))
        .collect();
    let get = |name: &str| -> Result<f64> {
        fields
            .get(name)
            .and_then(|v| v.parse().ok())
            .ok_or_else(|| format!("the MEASURED line has no {name}").into())
    };
    Ok(Replay {
        imu_samples: get("imu_samples")? as u64,
        gnss_fixes: get("gnss_fixes")? as u64,
        duration_s: get("duration_s")?,
        horizontal_rms_m: get("horizontal_rms_m")?,
        vertical_rms_m: get("vertical_rms_m")?,
        max_axis_bias_m: get("max_axis_bias_m")?,
        replay_s: get("replay_s")?,
    })
}

fn count_tests(root: &Path) -> Result<usize> {
    println!("=== counting the tests");
    let output = Command::new("cargo")
        .current_dir(root)
        .args([
            "test",
            "--release",
            "--workspace",
            "--exclude",
            "drifters-interop",
        ])
        .args(["--all-features", "--", "--list"])
        .stderr(Stdio::inherit())
        .output()?;
    if !output.status.success() {
        return Err("listing the tests failed".into());
    }
    let stdout = String::from_utf8(output.stdout)?;
    Ok(stdout.lines().filter(|l| l.ends_with(": test")).count())
}

/// `1.100` from `rustc 1.100.0 (...)`.
fn rust_version() -> Result<String> {
    let output = Command::new("rustc").arg("--version").output()?;
    let text = String::from_utf8(output.stdout)?;
    let version = text
        .split_whitespace()
        .nth(1)
        .ok_or("rustc printed no version")?;
    let mut parts = version.split('.');
    match (parts.next(), parts.next()) {
        (Some(major), Some(minor)) => Ok(format!("{major}.{minor}")),
        _ => Err(format!("unexpected rustc version: {version}").into()),
    }
}

/// The `replayed in 2.3 s` the README has now.
fn existing_replay_time(readme: &str) -> Result<f64> {
    readme
        .split_once("replayed in ")
        .and_then(|(_, rest)| rest.split_once(" s[^machine]"))
        .and_then(|(seconds, _)| seconds.parse().ok())
        .ok_or_else(|| "the README has no `replayed in N s[^machine]`".into())
}

const FOOTNOTE_START: &str =
    "[^machine]: The release-build regression test, file parsing included, on ";

/// The machine the README's footnote names now, so that a run without
/// `--machine` keeps it. The footnote is wrapped, so it is read as one
/// paragraph with its whitespace collapsed.
fn existing_machine(readme: &str) -> Result<String> {
    let start = readme
        .find("[^machine]:")
        .ok_or("the README has no [^machine] footnote; pass --machine")?;
    let paragraph = readme[start..].split("\n\n").next().unwrap_or_default();
    let flat = paragraph.split_whitespace().collect::<Vec<_>>().join(" ");
    let machine = flat
        .strip_prefix(FOOTNOTE_START)
        .and_then(|rest| rest.rsplit_once(", Rust "))
        .map(|(machine, _)| machine)
        .ok_or("the [^machine] footnote is not in the generated form; pass --machine")?;
    Ok(machine.to_string())
}

// --- rendering -----------------------------------------------------------

/// `1 599 280`: digits grouped by threes with a space, as the docs write them.
fn grouped(n: u64) -> String {
    let digits = n.to_string();
    let mut out = String::new();
    for (i, c) in digits.chars().enumerate() {
        if i > 0 && (digits.len() - i).is_multiple_of(3) {
            out.push(' ');
        }
        out.push(c);
    }
    out
}

/// One decimal place, a half rounded away from zero: `15.25` is `15.3`.
fn one_decimal(x: f64) -> String {
    format!("{:.1}", (x * 10.0).round() / 10.0)
}

/// A whole number of percent, a half rounded away from zero.
fn percent(fraction: f64) -> String {
    format!("{:.0} %", (fraction * 100.0).round())
}

fn kib(bytes: u64) -> String {
    one_decimal(bytes as f64 / 1024.0)
}

/// Wrap `text` at 80 columns, continuing with `indent`. A `%` stays on the line
/// of the number it follows.
fn wrap(text: &str, indent: &str) -> String {
    let mut words: Vec<String> = Vec::new();
    for word in text.split_whitespace() {
        match words.last_mut() {
            Some(last) if word.starts_with('%') => {
                last.push(' ');
                last.push_str(word);
            }
            _ => words.push(word.to_string()),
        }
    }
    let mut out = String::new();
    let mut line = String::new();
    for word in &words {
        let width = if out.is_empty() {
            80
        } else {
            80 - indent.len()
        };
        if !line.is_empty() && line.len() + 1 + word.len() > width {
            out.push_str(&line);
            out.push('\n');
            out.push_str(indent);
            line.clear();
        }
        if !line.is_empty() {
            line.push(' ');
        }
        line.push_str(word);
    }
    out.push_str(&line);
    out
}

fn render_performance(
    harness: &Harness,
    replay: &Replay,
    tests: usize,
    eqf_ceiling: u64,
    machine: &str,
    rust: &str,
) -> Result<String> {
    let m4 = &harness[&("m4", "default")];
    let m4_reduced = &harness[&("m4", "reduced")];
    let eqf_peak = m4
        .peaks
        .iter()
        .filter(|(label, _)| label.starts_with("PEAK_EQF"))
        .map(|(_, bytes)| *bytes)
        .max()
        .ok_or("the harness reported no PEAK_EQF")?;
    let bias = if replay.max_axis_bias_m < 0.001 {
        "below 1 mm".to_string()
    } else {
        format!(
            "at most {} mm",
            one_decimal(replay.max_axis_bias_m * 1000.0)
        )
    };
    let ceiling = if eqf_ceiling.is_multiple_of(1024) {
        (eqf_ceiling / 1024).to_string()
    } else {
        kib(eqf_ceiling)
    };
    let rows = [
        "| | measured |".to_string(),
        "|---|---|".to_string(),
        format!(
            "| **Accuracy** | **{} cm** horizontal, {} cm vertical RMS over {} minutes of real driving |",
            one_decimal(replay.horizontal_rms_m * 100.0),
            one_decimal(replay.vertical_rms_m * 100.0),
            (replay.duration_s / 60.0).round(),
        ),
        format!(
            "| | {} k IMU samples at {} Hz, {} RTK fixes, replayed in {} s[^machine] |",
            grouped((replay.imu_samples as f64 / 1000.0).round() as u64),
            (replay.imu_samples as f64 / replay.duration_s).round(),
            grouped(replay.gnss_fixes),
            one_decimal(replay.replay_s),
        ),
        format!("| | per-axis bias {bias} |"),
        format!(
            "| **Footprint** | **{} KiB** peak stack (15-state), {} KiB (21-state), on Cortex-M4, late fixes included |",
            kib(m4_reduced.peak("PEAK")?),
            kib(m4.peak("PEAK")?),
        ),
        format!(
            "| | {} KiB for the equivariant filter's engine, under a {ceiling} KiB ceiling |",
            kib(eqf_peak),
        ),
        "| **Safety** | the data path links **zero** `core::panicking` symbols |".to_string(),
        "| **Dependencies** | **one** on the filter path: `libm`. Protobuf adds `micropb` and `heapless`; `defmt` and `serde` are opt-in features |".to_string(),
        "| **Estimators** | two, behind one trait: a 21-state **ESKF** and an **equivariant filter** |".to_string(),
        format!(
            "| **Tests** | {} with every feature on, leaving out the opt-in `drifters-interop` adapters, plus fuzzing and a bare-metal QEMU harness |",
            grouped(tests as u64),
        ),
    ];
    let footnote = wrap(&format!("{FOOTNOTE_START}{machine}, Rust {rust}."), "    ");
    Ok(format!("{}\n\n{footnote}", rows.join("\n")))
}

/// The ESKF's four rows come from its four configurations; the EqF does not
/// depend on the ESKF's features, so its rows come from the default build.
const INSTRUCTION_ROWS: [(&str, &str, &str); 8] = [
    ("ESKF, 21-state", "default", "INSTRUCTIONS"),
    ("ESKF, 21-state, `f32-covariance`", "f32", "INSTRUCTIONS"),
    (
        "ESKF, 15-state (`reduced-state`)",
        "reduced",
        "INSTRUCTIONS",
    ),
    (
        "ESKF, 15-state, `f32-covariance`",
        "reduced-f32",
        "INSTRUCTIONS",
    ),
    ("EqF engine, dense `f64`", "default", "INSTRUCTIONS_EQF"),
    (
        "EqF engine, factored `f32`",
        "default",
        "INSTRUCTIONS_EQF_F32",
    ),
    (
        "EqF engine, dense, Earth in the group",
        "default",
        "INSTRUCTIONS_EQF_EARTH",
    ),
    (
        "EqF engine, factored, Earth in the group",
        "default",
        "INSTRUCTIONS_EQF_EARTH_F32",
    ),
];

fn render_instructions(harness: &Harness) -> Result<String> {
    let mut out = String::from(
        "| | Cortex-M4, `f64` in software | Cortex-M7, `f64` in hardware | Cortex-M7, `opt-level = 3` |\n\
         |---|---|---|---|",
    );
    for (row, configuration, label) in INSTRUCTION_ROWS {
        out.push_str(&format!("\n| {row} |"));
        for build in &BUILDS {
            let count = harness[&(build.name, configuration)].instructions(label)?;
            out.push_str(&format!(" {} |", grouped(count)));
        }
    }
    Ok(out)
}

fn render_testing(harness: &Harness, rust: &str) -> Result<String> {
    let m4 = |configuration: &'static str, label: &str| {
        harness[&("m4", configuration)].count_and_ticks(label)
    };
    let mut out = format!(
        "Per `add_imu` on `mps2-an386`, the mean of 200 steps, measured with Rust {rust}:\n\n\
         | configuration | instructions | SysTick ticks |\n\
         |---|---|---|"
    );
    for (row, configuration, label) in INSTRUCTION_ROWS {
        // This table names the ESKF's default precision, which the README's
        // column headings carry instead.
        let row = if row == "ESKF, 21-state" {
            "ESKF, 21-state, `f64`"
        } else {
            row
        };
        let (count, ticks) = m4(configuration, label)?;
        out.push_str(&format!(
            "\n| {row} | **{}** | {} |",
            grouped(count),
            grouped(ticks)
        ));
    }

    let n = |configuration, label| -> Result<f64> { Ok(m4(configuration, label)?.0 as f64) };
    let eskf = n("default", "INSTRUCTIONS")?;
    let eskf_f32 = n("f32", "INSTRUCTIONS")?;
    let reduced = n("reduced", "INSTRUCTIONS")?;
    let reduced_f32 = n("reduced-f32", "INSTRUCTIONS")?;
    let eqf = n("default", "INSTRUCTIONS_EQF")?;
    let eqf_f32 = n("default", "INSTRUCTIONS_EQF_F32")?;
    let earth = n("default", "INSTRUCTIONS_EQF_EARTH")?;
    let earth_f32 = n("default", "INSTRUCTIONS_EQF_EARTH_F32")?;
    let ratio = |x: f64| format!("{:.2}", (x * 100.0).round() / 100.0);
    let added = |x: f64| format!("{} %", one_decimal((x - 1.0) * 100.0));
    let prose = format!(
        "The single-precision covariance removes **{}** of the work at 21 states and \
         {} at 15, at no measurable cost in accuracy. Dropping the six scale-factor \
         states removes {}. For the equivariant filter, factoring the covariance and \
         holding it in `f32` removes **{}**, also at no measurable cost in accuracy; it \
         lands at {} times the ESKF with `f32-covariance`, where the dense form is {} \
         times the ESKF in `f64`. Carrying the Earth's rotation in the group adds {} to \
         the dense form and {} to the factored one.",
        percent(1.0 - eskf_f32 / eskf),
        percent(1.0 - reduced_f32 / reduced),
        percent(1.0 - reduced / eskf),
        percent(1.0 - eqf_f32 / eqf),
        ratio(eqf_f32 / eskf_f32),
        ratio(eqf / eskf),
        added(earth / eqf),
        added(earth_f32 / eqf_f32),
    );
    out.push_str("\n\n");
    out.push_str(&wrap(&prose, ""));
    Ok(out)
}

/// Replace each named block's contents, leaving its markers and the text around
/// it alone. A missing marker is an error rather than a silent no-op.
fn replace_blocks(text: &str, blocks: &[(&str, String)]) -> Result<String> {
    let mut text = text.to_string();
    for (name, body) in blocks {
        let begin = format!("<!-- generated by `cargo xtask measure`: {name} -->");
        let end = format!("<!-- end of generated: {name} -->");
        let start = text
            .find(&begin)
            .ok_or_else(|| format!("no `{begin}` marker"))?
            + begin.len();
        let stop = start
            + text[start..]
                .find(&end)
                .ok_or_else(|| format!("no `{end}` marker"))?;
        text.replace_range(start..stop, &format!("\n\n{body}\n\n"));
    }
    Ok(text)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn digits_are_grouped_by_threes() {
        assert_eq!(grouped(7), "7");
        assert_eq!(grouped(858), "858");
        assert_eq!(grouped(3413), "3 413");
        assert_eq!(grouped(1_599_280), "1 599 280");
    }

    #[test]
    fn a_half_rounds_up() {
        assert_eq!(one_decimal(15.25), "15.3");
        assert_eq!(kib(15_616), "15.3");
        assert_eq!(kib(8_512), "8.3");
        assert_eq!(percent(0.7811), "78 %");
    }

    #[test]
    fn a_block_is_replaced_between_its_markers_only() {
        let text = "before\n<!-- generated by `cargo xtask measure`: t -->\nold\n\
                    <!-- end of generated: t -->\nafter\n";
        let new = replace_blocks(text, &[("t", "new".to_string())]).unwrap();
        assert_eq!(
            new,
            "before\n<!-- generated by `cargo xtask measure`: t -->\n\nnew\n\n\
             <!-- end of generated: t -->\nafter\n"
        );
        assert!(replace_blocks("no markers", &[("t", String::new())]).is_err());
    }

    #[test]
    fn a_harness_log_parses() {
        let log = "INSTRUCTIONS add_imu = 1599280 (39982 ticks; only under -icount shift=0)\n\
                   PEAK                           13232\n\
                   INSTRUCTIONS_EQF add_imu = 4509840 (112746 ticks; only under -icount shift=0)\n\
                   PEAK_EQF                       15616\n\
                   INSTRUCTIONS_ALIGN_WORST add_gnss = 58960 (1474 ticks; only under -icount shift=0)\n";
        let run = HarnessRun::parse(log).unwrap();
        assert_eq!(
            run.count_and_ticks("INSTRUCTIONS").unwrap(),
            (1_599_280, 39_982)
        );
        assert_eq!(run.instructions("INSTRUCTIONS_EQF").unwrap(), 4_509_840);
        assert_eq!(run.peak("PEAK_EQF").unwrap(), 15_616);
        assert!(HarnessRun::parse("INSTRUCTIONS add_imu = unmeasured").is_err());
    }

    #[test]
    fn a_percentage_is_not_split_from_its_number() {
        // Without the rule, `74` would end the first line and `%` start the next.
        let text = format!("{} adds 74 % at 15", "x".repeat(73));
        let wrapped = wrap(&text, "");
        assert!(wrapped.contains("74 %"), "{wrapped}");
        assert!(wrapped.lines().all(|line| line.len() <= 80), "{wrapped}");
        assert_eq!(
            existing_replay_time("replayed in 2.3 s[^machine] |").unwrap(),
            2.3
        );
    }

    #[test]
    fn the_footnote_round_trips_its_machine() {
        let readme = format!(
            "{FOOTNOTE_START}a\n    Lenovo Slim 7x: 12 cores, Linux under WSL2, Rust 1.100.\n"
        );
        assert_eq!(
            existing_machine(&readme).unwrap(),
            "a Lenovo Slim 7x: 12 cores, Linux under WSL2"
        );
    }
}
